from flask import Flask, request, redirect
import re

app = Flask(__name__)

# Expression régulière pour correspondre à une chaîne commençant par un ou plusieurs caractères alphanumériques ou traits d'union, suivis d'un point
pattern = re.compile(r'^[a-zA-Z0-9\-]+\.$')

@app.route('/')
def index():
    # Récupérer le paramètre de requête 'cible'
    target = request.args.get('cible', '')

    # Vérifier si la cible correspond à l'expression régulière
    if pattern.match(target):
        return redirect(target)
    else:
        return redirect('/')

if __name__ == '__main__':
    app.run(debug=True)

