import re
from flask import Flask, redirect, request

app = Flask(__name__)

# রেগুলার এক্সপ্রেশন যা এক বা একাধিক বর্ণসংখ্যার অক্ষর বা হাইফেন দিয়ে একটি পিরিয়ড অনুসরণ করে
pattern = re.compile(r'^[a-zA-Z0-9-]+\.$')

@app.route('/')
def index():
    # টার্গেট কোয়েরি প্যারামিটার থেকে মান নিন
    target = request.args.get('target', '')

    # রেগুলার এক্সপ্রেশনের সাথে মেলানো হচ্ছে কিনা তা পরীক্ষা করুন
    if pattern.match(target):
        return redirect(target)
    else:
        return redirect('/')  # রুটে রিডাইরেক্ট করুন

if __name__ == '__main__':
    app.run(debug=True)

