import re
from urllib.parse import urlparse, parse_qs

def redirect_user(target):
    # 正規表現: 1 つ以上の英数字またはハイフンで始まり、その後にピリオドが続く文字列
    pattern = r'^[a-zA-Z0-9-]+\.[a-zA-Z0-9-]+$'

    # ターゲットが空の場合、ルートにリダイレクト
    if not target:
        return "/"

    # ターゲットが正規表現と一致するかチェック
    if re.match(pattern, target):
        return target
    else:
        return "/"
